    """Merge overlapping [start, end] intervals; return them sorted by start. Touching intervals merge."""
    if not iv:
        return []
    # Ensure each interval has two elements and start <= end
    cleaned = []
    for a in iv:
        if not isinstance(a, (list, tuple)) or len(a) != 2:
            raise ValueError("Each interval must be a list or tuple of two elements")
        start, end = a
        if start > end:
            start, end = end, start
        cleaned.append([start, end])
    cleaned.sort(key=lambda x: x[0])
    merged = [cleaned[0]]
    for cur in cleaned[1:]:
        last = merged[-1]
        if cur[0] <= last[1]:  # overlap or touching
            last[1] = max(last[1], cur[1])
        else:
            merged.append(cur)
    return merged

