def camel_to_snake(s: str) -> str:
    """Convert camelCase or PascalCase to snake_case.

    Consecutive capital letters are treated as a single word (e.g. HTTPServer -> http_server).
    """
    if not s:
        return ''
    parts = []
    current = []
    for i, ch in enumerate(s):
        if ch.isupper():
            # If we are in the middle of a word and the next char is lower case, start a new word
            if current and (i + 1 < len(s) and s[i + 1].islower()):
                parts.append(''.join(current))
                current = [ch.lower()]
            else:
                current.append(ch.lower())
        else:
            current.append(ch)
    if current:
        parts.append(''.join(current))
    return '_'.join(parts)

